                . '<form method="post">' . $hidden . '<input type="hidden" name="action" value="google_user_auth">'
                . '<input type="hidden" name="login" value="' . $encoded . '">'
                . '<input type="hidden" name="google_user_version" value="' . $googleVersion . '">'
                . '<label>Adresse e-mail Google autorisée<input name="google_allowed_email" type="email" maxlength="254" value="' . MusicbandEscape($googleAllowed) . '" autocomplete="off"></label>'
                . '<label class="Musicband-check-label"><input type="checkbox" class="Musicband-checkbox" name="google_enabled" value="1"' . ($googleEnabled ? ' checked' : '') . '> Autoriser Google pour ce compte</label>';
            if ($googleSub !== '') {
                $content .= '<p>Identité Google liée' . ($googleLinkedAt !== '' ? ' le ' . MusicbandDisplayDate($googleLinkedAt, true, true) : '')
                    . ($googleLastLogin !== '' ? ' · Dernière connexion : ' . MusicbandDisplayDate($googleLastLogin, true, true) : '') . '.</p>'
                    . '<p>Modifier l’adresse conserve l’identité liée. Pour autoriser une autre identité, confirmer son remplacement.</p>'
                    . '<label class="Musicband-check-label"><input type="checkbox" class="Musicband-checkbox" name="google_replace_identity" value="yes"> Confirmer le remplacement de l’identité Google liée</label>';
            } else {
                $content .= '<p>L’identité Google sera liée à la première connexion vérifiée, après activation du compte. Aucun rôle ne sera attribué par Google.</p>';
            }
            $content .= '<button>Enregistrer l’accès Google</button></form>';
            if ($googleEnabled) {
                $content .= '<form method="post">' . $hidden . '<input type="hidden" name="action" value="google_user_revoke">'
                    . '<input type="hidden" name="login" value="' . $encoded . '">'
                    . '<input type="hidden" name="google_user_version" value="' . $googleVersion . '"><button>Révoquer Google</button></form>';
            }
            $content .= '</details>';
        }
        $advAllowed = advancedNotificationsUserAllowed((string)$login);
        $content .= '<details><summary>Notifications personnalisées · ' . ($advAllowed ? 'Autorisées' : 'Non autorisées') . '</summary>' .
            '<form method="post">' . $hidden .
            '<input type="hidden" name="action" value="user_advanced_notifications">' .
            '<input type="hidden" name="login" value="' . $encoded . '">' .
            '<input type="hidden" name="config_tab" value="utilisateurs">' .
            '<label class="Musicband-check-label"><input type="checkbox" class="Musicband-checkbox" name="advanced_notifications_allowed" value="1"' . ($advAllowed ? ' checked' : '') . '> Autoriser les notifications personnalisées pour ce compte</label>' .
            '<button>Enregistrer l’autorisation</button>' .
            '</form></details>';
        if ($isInvited) $content .= '<p>Un renvoi conserve le rôle et les autorisations Google actuels.</p><form method="post">' . $hidden . '<input type="hidden" name="action" value="invite"><input type="hidden" name="email" value="' . $email . '"><input type="hidden" name="role" value="' . MusicbandEscape($accountRole) . '"><button>Renvoyer l’invitation</button></form>';
        if (!$isInvited && MusicbandAccountIsActive($entry) && $email !== '') $content .= '<form method="post">' . $hidden . '<input type="hidden" name="action" value="reset"><input type="hidden" name="login" value="' . $encoded . '"><button>Envoyer un lien de réinitialisation</button></form>';
        if ($login !== $user['login']) $content .= '<form method="post">' . $hidden . '<input type="hidden" name="action" value="delete"><input type="hidden" name="login" value="' . $encoded . '"><button>Supprimer cet accès</button></form>';
        $content .= '</div>';
    }
    $content.='</section><p class="config-top"><a href="#config-navigation">↑ Sections de configuration</a></p></div>';
    $content.='<div id="config-aide" class="config-section" role="region" aria-labelledby="config-aide-title"><h2 id="config-aide-title">Gestion de l’aide</h2>';
    require_once __DIR__ . '/help_service.php';
    $content.=MusicbandHelpAdminForm($hidden);
    $content.='<p class="config-top"><a href="#config-navigation">↑ Sections de configuration</a></p></div>';
    foreach($orderedModules as $module=>$label){
        $content.='<div id="config-'.MusicbandEscape($module).'" class="config-section" role="region" aria-labelledby="config-'.MusicbandEscape($module).'-title"><h2 id="config-'.MusicbandEscape($module).'-title">'.MusicbandEscape($label).'</h2>';
        if(in_array($module,businessModules(),true))$content.=fieldLayoutForms($hidden,$module);
        if($module==='songs')$content.=dashboardSongsFilterAdminForm($hidden, 'songs');
        if($module==='concerts')$content.=concertsCalendarSettingsForm($hidden).concertsCalendarTemplateForm($hidden).concertsWordPressForm($hidden);
        if($module==='agenda')$content.=workspaceCalendarSettingsForm($hidden);
        if($module==='devis_factures')$content.=documentsMailSettingsForm($hidden).documentsPdfSettingsForm($hidden).documentsGoogleSettingsForm($hidden);
        if($module==='accounting')$content.=financeOpeningForm(MusicbandRbacDb(),$hidden);
        if($module==='tasks')$content.=tasksCategoriesConfigForm($hidden);
        if(in_array($module,['setlist','sound'],true))$content.='<p>Les icônes se règlent dans <a href="#config-icones">Icônes</a> ; le statut bêta et les notifications dans <a href="#config-general">Général</a>. Les droits d’accès et d’action se règlent dans <a href="#config-utilisateurs">Utilisateurs</a>.</p>';
        $content.='<p class="config-top"><a href="#config-navigation">↑ Sections de configuration</a></p></div>';
    }
    // Validation PHP explicite, même si l’autoremplissage propose une valeur invalide.
    $content = str_replace('<form method="post">', '<form method="post" novalidate action="' . MusicbandEscape(MusicbandBase()) . 'admin.php">', $content);
    $layoutScript=base64_decode('',true);
    $tabsScript=<<<'JS'
(()=>{
  const nav=document.getElementById('config-navigation');
  if(!nav)return;
  const tabs=[...nav.querySelectorAll('a[href^="#config-"]')];
  const panels=tabs.map(tab=>document.getElementById(tab.hash.slice(1)));
  if(!tabs.length||panels.some(panel=>!panel))return;
  nav.setAttribute('role','tablist');
  tabs.forEach((tab,i)=>{
    tab.id='config-tab-'+panels[i].id.slice(7);
    tab.setAttribute('role','tab');tab.setAttribute('aria-controls',panels[i].id);
    panels[i].setAttribute('role','tabpanel');panels[i].setAttribute('aria-labelledby',tab.id);
    panels[i].querySelectorAll('form[method="post"]').forEach(form=>{
      const input=document.createElement('input');input.type='hidden';input.name='config_tab';input.value=panels[i].id.slice(7);form.append(input);
    });
  });
  function activate(index,focus=false){
    tabs.forEach((tab,i)=>{const active=i===index;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;panels[i].hidden=!active;});
    if(focus){tabs[index].focus({preventScroll:true});tabs[index].scrollIntoView({block:'nearest',inline:'nearest'});}
  }
  function fromHash(){const index=tabs.findIndex(tab=>tab.hash===location.hash);activate(index<0?0:index);}
  function choose(index,focus=false){if(location.hash!==tabs[index].hash)history.pushState(null,'',tabs[index].hash);activate(index,focus);}
  tabs.forEach((tab,index)=>{
    tab.addEventListener('click',event=>{if(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();choose(index);});
    tab.addEventListener('keydown',event=>{
      let next=index;
      if(event.key==='ArrowRight')next=(index+1)%tabs.length;
      else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;
      else if(event.key==='Home')next=0;
      else if(event.key==='End')next=tabs.length-1;
      else if(event.key===' ')next=index;
      else return;
      event.preventDefault();choose(next,true);
    });
  });
  // Les renvois Général/Utilisateurs internes ouvrent aussi le bon onglet.
  nav.parentElement.addEventListener('click',event=>{
    const link=event.target.closest('a[href^="#config-"]');
    if(!link||nav.contains(link)||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
    const index=tabs.findIndex(tab=>tab.hash===link.hash);
    if(index>=0){event.preventDefault();choose(index,true);}
  });
  window.addEventListener('hashchange',fromHash);window.addEventListener('popstate',fromHash);
  fromHash();nav.parentElement.classList.add('config-tabs-ready');
})();
JS;
    MusicbandScreen('Configuration', $content, ($layoutScript?:'')."\n;\n".$tabsScript."\n;\n".MusicbandHelpEditorScript().($message === '' ? '' : "\ndocument.getElementById('admin-status').focus();"));
} catch (Throwable $e) { MusicbandFail('Gestion des comptes indisponible.'); }
